**Migration Script (merge-duplicates.sql):**
```sql
-- Create merge_log table
CREATE TABLE IF NOT EXISTS merge_log (
  id SERIAL PRIMARY KEY,
  primary_user_id INTEGER NOT NULL,
  duplicate_user_id INTEGER NOT NULL,
  email VARCHAR NOT NULL,
  merged_at TIMESTAMP DEFAULT NOW(),
  orders_moved INTEGER DEFAULT 0,
  comments_moved INTEGER DEFAULT 0,
  files_moved INTEGER DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_users_email_lower ON users (LOWER(email));

DO $$
DECLARE
  dup RECORD;
  batch_count INTEGER := 0;
  total_merged INTEGER := 0;
BEGIN
  RAISE NOTICE 'Starting duplicate merge...';

  FOR dup IN
    SELECT 
      MIN(u1.id) as primary_id,
      u2.id as duplicate_id,
      u1.email
    FROM users u1
    JOIN users u2 ON LOWER(u1.email) = LOWER(u2.email) AND u1.id < u2.id
    WHERE u1.deleted_at IS NULL AND u2.deleted_at IS NULL
    GROUP BY u2.id, u1.email
    ORDER BY u1.id
    LIMIT 100  -- Batch size
  LOOP
    -- Reassign orders
    UPDATE orders SET user_id = dup.primary_id WHERE user_id = dup.duplicate_id;

    -- Reassign comments
    UPDATE comments SET user_id = dup.primary_id WHERE user_id = dup.duplicate_id;

    -- Reassign file_uploads
    UPDATE file_uploads SET user_id = dup.primary_id WHERE user_id = dup.duplicate_id;

    -- Log the merge
    INSERT INTO merge_log (primary_user_id, duplicate_user_id, email, orders_moved, comments_moved, files_moved)
    SELECT dup.primary_id, dup.duplicate_id, dup.email,
           (SELECT COUNT(*) FROM orders WHERE user_id = dup.primary_id),
           (SELECT COUNT(*) FROM comments WHERE user_id = dup.primary_id),
           (SELECT COUNT(*) FROM file_uploads WHERE user_id = dup.primary_id);

    -- Soft-delete duplicate
    UPDATE users SET deleted_at = NOW() WHERE id = dup.duplicate_id;

    batch_count := batch_count + 1;
    total_merged := total_merged + 1;

    IF batch_count % 10 = 0 THEN
      RAISE NOTICE 'Merged % duplicates so far...', total_merged;
    END IF;
  END LOOP;

  RAISE NOTICE 'Merge complete. Total merged: %', total_merged;
END $$;
```

**Rollback Script (rollback-merge.sql):**
```sql
DO $$
DECLARE
  merge_rec RECORD;
BEGIN
  RAISE NOTICE 'Starting rollback...';

  FOR merge_rec IN SELECT * FROM merge_log ORDER BY id DESC LOOP
    -- Reassign orders back
    UPDATE orders SET user_id = merge_rec.duplicate_user_id WHERE user_id = merge_rec.primary_user_id;

    -- Reassign comments back
    UPDATE comments SET user_id = merge_rec.duplicate_user_id WHERE user_id = merge_rec.primary_user_id;

    -- Reassign files back
    UPDATE file_uploads SET user_id = merge_rec.duplicate_user_id WHERE user_id = merge_rec.primary_user_id;

    -- Restore duplicate account
    UPDATE users SET deleted_at = NULL WHERE id = merge_rec.duplicate_user_id;
  END LOOP;

  -- Clear merge log
  TRUNCATE merge_log;

  RAISE NOTICE 'Rollback complete.';
END $$;
```
